/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=deal, operation=get
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get an activity */
export type PipedriveV2DealGetParams = {
  resource: 'deal';
  operation: 'get';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the deal to get
 * @default 0
 */
    dealId?: number | Expression<number>;
/**
 * Whether to show raw Pipedrive field keys and option IDs instead of human-readable names in output
 * @default false
 */
    rawCustomFieldOutput?: boolean | Expression<boolean>;
};

export type PipedriveV2DealGetOutput = {
  acv?: number;
  add_time?: string;
  archive_time?: unknown;
  arr?: number;
  channel?: unknown;
  channel_id?: unknown;
  close_time?: unknown;
  creator_user_id?: number;
  currency?: string;
  custom_fields?: Record<string, unknown>;
  expected_close_date?: unknown;
  id?: number;
  is_archived?: boolean;
  is_deleted?: boolean;
  label_ids?: Array<unknown>;
  local_close_date?: unknown;
  local_lost_date?: unknown;
  local_won_date?: unknown;
  lost_reason?: unknown;
  lost_time?: unknown;
  mrr?: number;
  org_id?: number;
  origin?: string;
  origin_id?: unknown;
  owner_id?: number;
  person_id?: number;
  pipeline_id?: number;
  probability?: unknown;
  stage_change_time?: unknown;
  stage_id?: number;
  status?: string;
  title?: string;
  update_time?: string;
  value?: number;
  visible_to?: number;
  won_time?: unknown;
};

export type PipedriveV2DealGetNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2DealGetParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2DealGetOutput>;
};